import React, { Component } from "react";
import "./HelpAnimalModal.css";
import ChatComponent from "./chat";

class HelpAnimalModal extends Component {
  constructor(props) {
    super(props);
    this.state = {
      microchipId: "",
      showChat: false,
    };
  }

  handleChange = (event) => {
    this.setState({ microchipId: event.target.value });
  };

  handleSubmit = () => {
    this.setState({ showChat: true });
  };

  handleEndChat = () => {
    this.setState({ showChat: false });
    this.props.onClose();
  };

  render() {
    if (!this.props.show) {
      return null;
    }

    return (
      <div className="custom-modal">
        <div className="custom-modal-content">
          <span className="custom-modal-close" onClick={this.props.onClose}>&times;</span>
          {this.state.showChat ? (
            <ChatComponent onEndChat={this.handleEndChat} />
          ) : (
            <>
              <h2>You found a lost pet</h2>
              <p>Please write the ID of the microchip of the pet</p>
              <input
                type="text"
                value={this.state.microchipId}
                onChange={this.handleChange}
                className="custom-modal-input"
              />
              <button onClick={this.handleSubmit} className="custom-modal-button">Open a chat with the owner</button>
            </>
          )}
        </div>
      </div>
    );
  }
}

export default HelpAnimalModal;
